package com.example.domain.model.i18n

internal object DuaAr1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("عند الاستيقاظ من النوم", "الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور.", "تُقال فور الاستيقاظ من النوم شكرًا لله.", "كان النبي ﷺ يقولها عند الاستيقاظ — بداية اليوم بالشكر وذكر الآخرة."),
        "dua_leaving_home" to DuaText("عند الخروج من المنزل", "بسم الله، توكلت على الله، ولا حول ولا قوة إلا بالله.", "تُقال عند الخروج من المنزل طلبًا للحفظ.", "يقال للعبد عندئذٍ: هُديت وكُفيت ووُقيت، ويتنحى عنه الشيطان."),
        "dua_anxiety_distress" to DuaText("دعاء الهم والحزن", "اللهم إني أعوذ بك من الهم والحزن، والعجز والكسل، والبخل والجبن، وضلع الدين وغلبة الرجال.", "عند الهم والحزن وثقل الدين والضيق النفسي.", "كان النبي ﷺ يكثر من هذا الدعاء استعاذة من الهم والكسل والدين."),
        "dua_sayyidul_istighfar" to DuaText("سيد الاستغفار", "اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت، أعوذ بك من شر ما صنعت، أبوء لك بنعمتك علي، وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت.", "صباحًا ومساءً — أفضل دعاء للتوبة علّمه النبي ﷺ.", "من قالها موقنًا بها حين يمسي فمات دخل الجنة، وكذلك إن قالها حين يصبح."),
        "dua_parents" to DuaText("دعاء للوالدين", "رب ارحمهما كما ربياني صغيرًا.", "دعاء قرآني للوالدين مقابل تربيتهما في الصغر.", "أمر الله بهذا الدعاء للوالدين في القرآن الكريم."),
        "dua_entering_mosque" to DuaText("دخول المسجد", "اللهم افتح لي أبواب رحمتك.", "تُقال عند دخول المسجد بالقدم اليمنى.", "علّم النبي ﷺ هذا الدعاء عند دخول المسجد."),
        "dua_morning_asbahna" to DuaText("ذكر الصباح", "أصبحنا وأصبح الملك لله، والحمد لله، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير.", "دعاء مسنون يُقال في الصباح.", "بداية اليوم بالإقرار بملك الله ووحدانيته."),
        "dua_evening_amsayna" to DuaText("ذكر المساء", "أمسينا وأمسى الملك لله، والحمد لله، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير.", "دعاء مسنون يُقال في المساء.", "بداية الليل بالإقرار بملك الله ووحدانيته."),
        "dua_bismillah_la_yadurru" to DuaText("الحفظ من كل ضرر", "بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء، وهو السميع العليم.", "تُقال ثلاث مرات صباحًا ومساءً.", "من قالها ثلاثًا صباحًا ومساءً لم يضره شيء."),
        "dua_raditu_billahi" to DuaText("الرضا بالله ربًا", "رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد ﷺ نبيًا.", "تُقال ثلاث مرات صباحًا ومساءً.", "حقٌّ على الله أن يُرضيه يوم القيامة."),
        "dua_hasbiyallah" to DuaText("حسبي الله (كافيني)", "حسبي الله لا إله إلا هو، عليه توكلت وهو رب العرش العظيم.", "تُقال سبع مرات صباحًا ومساءً.", "آية قرآنية — يكفي الله همّ الدنيا والآخرة."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("سبحان الله وبحمده", "سبحان الله وبحمده.", "تُقال مئة مرة في اليوم.", "من قالها مئة مرة حُطّت خطاياه وإن كانت مثل زبد البحر."),
        "dua_tahleel_100" to DuaText("لا إله إلا الله وحده", "لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير.", "فضل عظيم لمن قالها مئة مرة في اليوم.", "كعدل عشر رقاب، وكُتبت له مئة حسنة، ومُحيت عنه مئة سيئة، وكانت له حرزًا من الشيطان يومه."),
        "dua_leaving_mosque" to DuaText("الخروج من المسجد", "اللهم إني أسألك من فضلك.", "تُقال عند الخروج من المسجد بالقدم اليسرى.", "طلب فضل الله ورزقه عند الخروج من المسجد."),
        "dua_after_adhan" to DuaText("بعد الأذان", "اللهم رب هذه الدعوة التامة والصلاة القائمة، آتِ محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته.", "بعد انتهاء الأذان مباشرة.", "من قالها حلّت له شفاعة النبي ﷺ يوم القيامة."),
        "dua_after_salah_istighfar" to DuaText("بعد الصلاة المفروضة", "أستغفر الله (ثلاثًا)، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام.", "مباشرة بعد التسليم من الصلاة.", "كان النبي ﷺ يقولها بعد كل صلاة مفروضة."),
        "dua_after_salah_help_dhikr" to DuaText("اللهم أعني على ذكرك", "اللهم أعني على ذكرك وشكرك وحسن عبادتك.", "بعد كل صلاة — وصية النبي ﷺ لمعاذ رضي الله عنه.", "وصية نبوية خاصة للإتقان والثبات في العبادة."),
        "dua_ayatul_kursi" to DuaText("آية الكرسي بعد الصلاة", "الله لا إله إلا هو الحي القيوم، لا تأخذه سنة ولا نوم، له ما في السماوات وما في الأرض، من ذا الذي يشفع عنده إلا بإذنه، يعلم ما بين أيديهم وما خلفهم، ولا يحيطون بشيء من علمه إلا بما شاء، وسع كرسيه السماوات والأرض، ولا يئوده حفظهما، وهو العلي العظيم.", "بعد كل صلاة مكتوبة وقبل النوم.", "من قرأها دبر كل صلاة مكتوبة لم يمنعه من دخول الجنة إلا أن يموت."),
        "dua_before_sleep" to DuaText("عند النوم", "باسمك اللهم أموت وأحيا.", "تُقال بعد الاستلقاء على الفراش.", "كان النبي ﷺ يقولها عند النوم."),
        "dua_sleep_tasbeeh" to DuaText("تسبيح فاطمة قبل النوم", "سبحان الله (٣٣)، الحمد لله (٣٣)، الله أكبر (٣٤).", "قبل النوم — علّمها النبي ﷺ لفاطمة وعلي رضي الله عنهما.", "قال النبي ﷺ: هو خير لكما من خادم."),
        "dua_sleep_qina_adhab" to DuaText("الوقاية من العذاب", "اللهم قني عذابك يوم تبعث عبادك.", "توضع اليد اليمنى تحت الخد، تُقال ثلاث مرات.", "تذكير بالموت والاستعداد للآخرة عند النوم."),
        "dua_bad_dream" to DuaText("عند رؤية الحلم المزعج", "أعوذ بالله من الشيطان الرجيم.", "عند رؤية حلم سيئ: ينفث عن يساره ثلاثًا ثم يتحول عن جنبه.", "لن يضره الحلم، ولا يخبر به أحدًا."),
        "dua_yunus" to DuaText("دعاء يونس عليه السلام", "لا إله إلا أنت سبحانك إني كنت من الظالمين.", "دعاء يونس عليه السلام في بطن الحوت — لكل كرب.", "ما دعا بها مسلم في شيء قط إلا استجاب الله له."),
        "dua_karb" to DuaText("دعاء الكرب الشديد", "لا إله إلا الله العظيم الحليم، لا إله إلا الله رب العرش العظيم، لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم.", "عند الكرب الشديد والضيق.", "كان النبي ﷺ يقولها عند الكرب."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("يا حي يا قيوم", "يا حي يا قيوم برحمتك أستغيث.", "عند اشتداد الأمر وثقله.", "كان النبي ﷺ يقولها إذا أهمه أمر."),
        "dua_hasbunallah" to DuaText("حسبنا الله ونعم الوكيل", "حسبنا الله ونعم الوكيل.", "عند الخوف من عدو أو خطر عظيم.", "قالها إبراهيم عليه السلام حين أُلقي في النار، وقالها النبي ﷺ عند الخطر."),
        "dua_entering_home" to DuaText("دخول المنزل", "بسم الله ولجنا وبسم الله خرجنا وعلى الله ربنا توكلنا.", "تُقال عند دخول المنزل مع ذكر اسم الله والسلام.", "من ذكر الله عند دخوله بيته وعند طعامه قال الشيطان: لا مبيت لكم ولا عشاء."),
        "dua_travel" to DuaText("دعاء السفر", "سبحان الذي سخر لنا هذا وما كنا له مقرنين، وإنا إلى ربنا لمنقلبون.", "تُقال عند الركوب بعد التكبير ثلاثًا.", "دعاء السفر المسنون للحفظ والبركة."),
        "dua_entering_market" to DuaText("دخول السوق", "لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت وهو حي لا يموت، بيده الخير وهو على كل شيء قدير.", "تُقال عند دخول السوق.", "ورد في الحديث فضل عظيم لها (ألف ألف حسنة)."),
        "dua_adam_forgiveness" to DuaText("دعاء آدم عليه السلام", "ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من الخاسرين.", "توبة آدم وحواء عليهما السلام.", "أول توبة في تاريخ البشرية — قبلها الله سبحانه."),
        "dua_abu_bakr" to DuaText("دعاء علّمه النبي لأبي بكر", "اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم.", "علّمه النبي ﷺ لأبي بكر الصديق ليقوله في الصلاة.", "دعاء مسنون يُقال في آخر الصلاة."),
        "dua_astaghfirullah_atubu" to DuaText("الاستغفار اليومي", "أستغفر الله وأتوب إليه.", "كان النبي ﷺ يستغفر أكثر من سبعين مرة في اليوم.", "قال ﷺ: إني لأستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرة."),
        "dua_laylatul_qadr" to DuaText("دعاء ليلة القدر", "اللهم إنك عفو تحب العفو فاعفُ عني.", "علّمه النبي ﷺ لعائشة رضي الله عنها لليلة القدر.", "دعاء خاص بالعشر الأواخر من رمضان وليلة القدر."),
        "dua_family_coolness" to DuaText("قرة العين من الأهل", "ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إمامًا.", "دعاء قرآني للزوجة الصالحة والذرية.", "لسكينة البيت والذرية الصالحة."),
        "dua_righteous_children" to DuaText("الذرية الصالحة", "رب هب لي من لدنك ذرية طيبة إنك سميع الدعاء.", "دعاء زكريا عليه السلام.", "دعاء قرآني لطلب الذرية."),
        "dua_ibrahim_prayer_family" to DuaText("إقامة الصلاة", "رب اجعلني مقيم الصلاة ومن ذريتي، ربنا وتقبل دعاء، ربنا اغفر لي ولوالدي وللمؤمنين يوم يقوم الحساب.", "دعاء إبراهيم عليه السلام لنفسه وذريته.", "يُقال غالبًا في آخر الصلاة."),
        "dua_newlywed" to DuaText("تهنئة العروسين", "بارك الله لك، وبارك عليك، وجمع بينكما في خير.", "تُقال لمن تزوج.", "تهنئة الزواج المسنونة."),
        "dua_before_eating" to DuaText("قبل الطعام", "بسم الله. (عند النسيان:) بسم الله في أوله وآخره.", "قبل الأكل، وإن نسي يقولها في الأثناء.", "بذكر البسملة لا يشارك الشيطان في الطعام."),
        "dua_after_eating" to DuaText("بعد الطعام", "الحمد لله الذي أطعمني هذا ورزقنيه من غير حول مني ولا قوة.", "بعد الانتهاء من الطعام.", "من قالها غُفر له ما تقدم من ذنبه."),
        "dua_host" to DuaText("دعاء للمُضيف", "اللهم بارك لهم فيما رزقتهم واغفر لهم وارحمهم.", "بعد تناول الطعام عند شخص لصاحب الضيافة.", "شكر المضيف بالطريقة المسنونة."),
        "dua_breaking_fast" to DuaText("عند الإفطار", "ذهب الظمأ وابتلت العروق وثبت الأجر إن شاء الله.", "عند الإفطار.", "كان النبي ﷺ يقولها عند الإفطار."),
        "dua_new_clothes" to DuaText("لبس الثوب الجديد", "اللهم لك الحمد أنت كسوتنيه، أسألك من خيره وخير ما صُنع له، وأعوذ بك من شره وشر ما صُنع له.", "عند لبس ثوب جديد باسمه.", "كان النبي ﷺ يقولها عند لبس الثوب الجديد."),
        "dua_rabbana_atina" to DuaText("خير الدنيا والآخرة", "ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار.", "أكثر دعاء كان النبي ﷺ يدعو به.", "دعاء جامع لكل خير في الدنيا والآخرة."),
        "dua_rabbi_zidni_ilma" to DuaText("زيادة العلم", "رب زدني علمًا.", "لطلب زيادة العلم.", "أمر الله النبي ﷺ بطلب الزيادة في العلم وحده."),
        "dua_musa_sharh_sadr" to DuaText("شرح الصدر (دعاء موسى)", "رب اشرح لي صدري، ويسر لي أمري، واحلل عقدة من لساني يفقهوا قولي.", "قبل امتحان أو خطاب أو أمر صعب.", "دعاء موسى عليه السلام — طمأنينة القلب وتيسير الأمر."),
        "dua_la_tuzigh" to DuaText("ثبات القلب", "ربنا لا تُزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة إنك أنت الوهاب.", "لثبات القلب على الهداية.", "دعاء الثبات على الإيمان."),
        "dua_ya_muqallib" to DuaText("يا مقلب القلوب", "يا مقلب القلوب ثبت قلبي على دينك.", "كان النبي ﷺ يكثر من هذا الدعاء.", "أكثر دعاء للنبي ﷺ حسب أم سلمة رضي الله عنها."),
        "dua_la_tuakhidhna" to DuaText("خواتيم سورة البقرة", "ربنا لا تؤاخذنا إن نسينا أو أخطأنا. ربنا ولا تحمل علينا إصرًا كما حملته على الذين من قبلنا. ربنا ولا تحملنا ما لا طاقة لنا به، واعف عنا واغفر لنا وارحمنا، أنت مولانا فانصرنا على القوم الكافرين.", "قبل النوم — آخر آيتين من سورة البقرة.", "من قرأهما في ليلة كفتاه."),
        "dua_visiting_sick" to DuaText("عيادة المريض", "أسأل الله العظيم رب العرش العظيم أن يشفيك.", "سبع مرات عند عيادة المريض.", "إن لم يحضر أجله شفاه الله."),
        "dua_ruqyah_pain" to DuaText("دعاء ألم الجسد", "أعوذ بالله وقدرته من شر ما أجد وأحاذر.", "توضع اليد على مكان الألم وتُقال ثلاثًا بسم الله ثم سبعًا هذا الدعاء.", "علّمه النبي ﷺ لعثمان بن أبي العاص رضي الله عنه للألم."),
        "dua_ruqyah_nabawi" to DuaText("رقية النبي ﷺ للمريض", "اللهم رب الناس أذهب الباس، اشفِ أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا.", "مع مسح يد على المريض.", "كان النبي ﷺ يقولها عند عيادة أهله."),
        "dua_kalimat_tammat" to DuaText("الاستعاذة بكلمات الله التامة", "أعوذ بكلمات الله التامات من شر ما خلق.", "عند النزول في مكان أو في المساء.", "من نزل منزلًا ثم قالها لم يضره شيء حتى يرتحل منه."),
        "dua_evil_eye" to DuaText("حفظ الأطفال من العين", "أعيذكما بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة.", "كان النبي ﷺ يرقي بها الحسن والحسين رضي الله عنهما.", "دعاء مسنون لحفظ الأطفال من العين والشر."),
        "dua_seeing_afflicted" to DuaText("عند رؤية مبتلى", "الحمد لله الذي عافاني مما ابتلاك به وفضلني على كثير ممن خلق تفضيلًا.", "عند رؤية مبتلى (تُقال في القلب).", "من قالها عُصم من ذلك البلاء."),
        "dua_istikhara" to DuaText("صلاة الاستخارة", "اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تقدر ولا أقدر، وتعلم ولا أعلم، وأنت علام الغيوب. اللهم إن كنت تعلم أن هذا الأمر خير لي في ديني ومعاشي وعاقبة أمري فاقدره لي ويسره لي ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر شر لي في ديني ومعاشي وعاقبة أمري فاصرفه عني واصرفني عنه، واقدر لي الخير حيث كان ثم أرضني به.", "بعد ركعتين نافلة عند طلب الخير في أمر مباح.", "كان النبي ﷺ يعلّم أصحابه الاستخارة كما يعلّمهم السورة من القرآن."),
        "dua_allahumma_bika_asbahna" to DuaText("اللهم بك أصبحنا", "اللهم بك أصبحنا وبك أمسينا، وبك نحيا وبك نموت وإليك النشور.", "في الصباح.", "كان النبي ﷺ يعلّمها لأصحابه صباحًا ومساءً."),
        "dua_allahumma_bika_amsayna" to DuaText("اللهم بك أمسينا", "اللهم بك أمسينا وبك أصبحنا، وبك نحيا وبك نموت وإليك المصير.", "في المساء.", "كان النبي ﷺ يعلّمها لأصحابه صباحًا ومساءً."),
        "dua_afiyah_morning" to DuaText("دعاء العافية", "اللهم إني أسألك العفو والعافية في الدنيا والآخرة.", "لم يكن النبي ﷺ يدعه صباحًا ومساءً.", "ما أُعطي أحد شيئًا خيرًا من العافية."),
        "dua_afini_fi_badani" to DuaText("العافية في البدن والسمع والبصر", "اللهم عافني في بدني، اللهم عافني في سمعي، اللهم عافني في بصري، لا إله إلا أنت.", "ثلاث مرات صباحًا ومساءً.", "دعاء لحفظ الصحة والحواس."),
        "dua_ya_hayyu_aslih" to DuaText("أصلح لي شأني كله", "يا حي يا قيوم برحمتك أستغيث، أصلح لي شأني كله ولا تكلني إلى نفسي طرفة عين.", "أوصى النبي ﷺ فاطمة رضي الله عنها بقولها صباحًا ومساءً.", "طلب عون الله في كل أمر."),
        "dua_subhanallah_adada_khalqihi" to DuaText("تسبيح جويرية رضي الله عنها", "سبحان الله وبحمده، عدد خلقه، ورضا نفسه، وزنة عرشه، ومداد كلماته.", "ثلاث مرات صباحًا — تعدل ذكر ساعات طويلة.", "هذه الكلمات الأربع ثلاث مرات أثقل من ذكر من الصباح إلى الظهر."),
        "dua_salawat" to DuaText("الصلاة الإبراهيمية", "اللهم صلِّ على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد. اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد.", "في الصلاة وفي كل وقت.", "من صلى على النبي ﷺ مرة صلى الله عليه بها عشرًا."),
        "dua_wudu_after" to DuaText("بعد الوضوء", "أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله. اللهم اجعلني من التوابين واجعلني من المتطهرين.", "بعد إتمام الوضوء.", "تُفتح له أبواب الجنة الثمانية يدخل من أيها شاء."),
        "dua_wudu_before" to DuaText("قبل الوضوء", "بسم الله.", "عند بدء الوضوء.", "من لم يذكر اسم الله فلا وضوء (كاملًا) له."),
        "dua_istiftah" to DuaText("دعاء الاستفتاح", "سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك.", "في بداية الصلاة بعد تكبيرة الإحرام.", "دعاء الاستفتاح المسنون."),
        "dua_ruku" to DuaText("في الركوع", "سبحان ربي العظيم.", "ثلاث مرات على الأقل في الركوع.", "تسبيح الركوع المسنون."),
        "dua_sujood" to DuaText("في السجود", "سبحان ربي الأعلى.", "ثلاث مرات على الأقل في السجود.", "أقرب ما يكون العبد من ربه وهو ساجد."),
        "dua_rising_ruku" to DuaText("عند الرفع من الركوع", "سمع الله لمن حمده، ربنا ولك الحمد.", "عند الرفع من الركوع والاعتدال قائمًا.", "من وافق قوله قول الملائكة غُفر له ما تقدم من ذنبه."),
        "dua_between_sajdas" to DuaText("بين السجدتين", "رب اغفر لي، رب اغفر لي.", "في الجلسة بين السجدتين.", "دعاء الجلسة المسنون."),
        "dua_before_salam_four" to DuaText("الاستعاذة من أربع قبل السلام", "اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن شر فتنة المسيح الدجال.", "بعد التشهد الأخير والصلاة على النبي، قبل السلام.", "أمر النبي ﷺ بالاستعاذة من هذه الأربع."),
        "dua_qunoot_witr" to DuaText("دعاء القنوت في الوتر", "اللهم اهدني فيمن هديت، وعافني فيمن عافيت، وتولني فيمن توليت، وبارك لي فيما أعطيت، وقني شر ما قضيت، فإنك تقضي ولا يُقضى عليك، وإنه لا يذل من واليت، تباركت ربنا وتعاليت.", "في صلاة الوتر — علّمه النبي ﷺ للحسن بن علي رضي الله عنه.", "دعاء القنوت المسنون في الوتر."),
        "dua_qunoot_hanafi" to DuaText("القنوت (اللهم إنا نستعينك)", "اللهم إنا نستعينك ونستغفرك ونؤمن بك ونتوكل عليك ونثني عليك الخير كله نشكرك ولا نكفرك ونخلع ونترك من يفجرك. اللهم إياك نعبد ولك نصلي ونسجد وإليك نسعى ونحفد نرجو رحمتك ونخشى عذابك إن عذابك بالكفار ملحق.", "في الوتر — على مذهب الأحناف.", "مروي عن عمر رضي الله عنه في القنوت."),
        "dua_sleep_aslamtu" to DuaText("آخر ما يُقال قبل النوم", "اللهم أسلمت نفسي إليك، وفوضت أمري إليك، وألجأت ظهري إليك، رغبة ورهبة إليك، لا ملجأ ولا منجى منك إلا إليك، آمنت بكتابك الذي أنزلت وبنبيك الذي أرسلت.", "بعد الوضوء والنوم على الجنب الأيمن — آخر ما يُقال.", "إن مات في تلك الليلة مات على الفطرة."),
        "dua_waking_night" to DuaText("عند الاستيقاظ ليلًا", "لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير. الحمد لله، وسبحان الله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله. اللهم اغفر لي.", "عند الاستيقاظ ليلًا.", "استُجيب دعاؤه، وإن توضأ وصلى قُبلت صلاته."),
        "dua_hamm_ibn_masud" to DuaText("دعاء الهم (ابن مسعود)", "اللهم إني عبدك، ابن عبدك، ابن أمتك، ناصيتي بيدك، ماضٍ فيّ حكمك، عدل فيّ قضاؤك، أسألك بكل اسم هو لك سميت به نفسك، أو أنزلته في كتابك، أو علمته أحدًا من خلقك، أو استأثرت به في علم الغيب عندك، أن تجعل القرآن ربيع قلبي، ونور صدري، وجلاء حزني، وذهاب همي.", "عند الهم والحزن — يبدله الله فرحًا.", "يذهب الله همه وحزنه ويبدله فرحًا."),
        "dua_difficulty_sahl" to DuaText("عند صعوبة الأمر", "اللهم لا سهل إلا ما جعلته سهلًا، وأنت تجعل الحزن إذا شئت سهلًا.", "عند صعوبة أمر ما.", "تيسير الامتحانات والأمور الصعبة."),
        "dua_musibah" to DuaText("عند المصيبة (الاسترجاع)", "إنا لله وإنا إليه راجعون. اللهم أجرني في مصيبتي وأخلف لي خيرًا منها.", "عند أي خسارة أو مصيبة.", "يعوض الله خيرًا — كما حصل لأم سلمة رضي الله عنها."),
        "dua_debt" to DuaText("التخلص من الدين", "اللهم اكفني بحلالك عن حرامك، وأغنني بفضلك عمن سواك.", "لسداد الدين — علّمه النبي ﷺ لعلي رضي الله عنه.", "لو كان عليه دين مثل جبل لأداه الله عنه."),
        "dua_anger" to DuaText("عند الغضب", "أعوذ بالله من الشيطان الرجيم.", "عند الغضب.", "قال النبي ﷺ: لو قالها لذهب غضبه."),
        "dua_waswasa" to DuaText("ضد وسوسة الإيمان", "آمنت بالله ورسله.", "عند وسوسة الشيطان في الإيمان.", "يقولها ويكفّ عن التفكير في الوسوسة."),
        "dua_travel_full" to DuaText("دعاء السفر الكامل", "اللهم إنا نسألك في سفرنا هذا البر والتقوى، ومن العمل ما ترضى. اللهم هوّن علينا سفرنا هذا واطوِ عنا بُعده. اللهم أنت الصاحب في السفر والخليفة في الأهل.", "عند بدء السفر بعد سبحان الذي سخر.", "دعاء السفر الكامل المسنون."),
        "dua_return_travel" to DuaText("عند العودة من السفر", "آيبون تائبون عابدون لربنا حامدون.", "عند العودة من السفر.", "كان النبي ﷺ يقولها عند الرجوع من السفر."),
        "dua_farewell_traveller" to DuaText("توديع المسافر", "أستودع الله دينك وأمانتك وخواتيم عملك.", "عند توديع المسافر.", "ما استُودع عند الله لا يضيع."),
        "dua_entering_town" to DuaText("النزول في مكان جديد", "أعوذ بكلمات الله التامات من شر ما خلق.", "عند النزول في مكان أو مدينة جديدة.", "لا يضره شيء حتى يرتحل من ذلك المكان."),
        "dua_boarding_ship" to DuaText("ركوب السفينة", "بسم الله مجراها ومرساها إن ربي لغفور رحيم.", "عند ركوب السفينة — قول نوح عليه السلام.", "آية قرآنية — دعاء سفينة نوح عليه السلام."),
        "dua_istighfar_hayyul_qayyum" to DuaText("الاستغفار بالحي القيوم", "أستغفر الله الذي لا إله إلا هو الحي القيوم وأتوب إليه.", "للتوبة.", "تُغفر ذنوبه ولو كان قد فرّ من الزحف."),
        "dua_rabbighfir_warham" to DuaText("رب اغفر وارحم", "رب اغفر وارحم وأنت خير الراحمين.", "دعاء قرآني — المغفرة والرحمة.", "آخر آية من سورة المؤمنون."),
        "dua_majlis_kaffarah" to DuaText("كفارة المجلس", "سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك.", "عند القيام من المجلس.", "تكفير لما حصل في المجلس من لغو."),
        "dua_jami_forgiveness" to DuaText("دعاء المغفرة الجامع", "اللهم اغفر لي خطيئتي وجهلي وإسرافي في أمري، وما أنت أعلم به مني.", "دعاء جامع كان النبي ﷺ يدعو به.", "دعاء شامل كان النبي ﷺ يكثر منه."),
        "dua_parents_nuh" to DuaText("دعاء نوح عليه السلام للوالدين", "رب اغفر لي ولوالدي ولمن دخل بيتي مؤمنًا وللمؤمنين والمؤمنات.", "للوالدين والمؤمنين.", "دعاء نوح عليه السلام."),
        "dua_shukr_parents" to DuaText("شكر نعمة الوالدين والذرية الصالحة", "رب أوزعني أن أشكر نعمتك التي أنعمت علي وعلى والدي وأن أعمل صالحًا ترضاه، وأصلح لي في ذريتي، إني تبت إليك وإني من المسلمين.", "دعاء قرآني لمن بلغ الأربعين.", "شكر النعمة والعمل الصالح وإصلاح الذرية في دعاء واحد."),
        "dua_intimacy" to DuaText("قبل معاشرة الزوجين", "بسم الله، اللهم جنبنا الشيطان وجنب الشيطان ما رزقتنا.", "قبل معاشرة الزوجين.", "إن قُدّر بينهما ولد لم يضره الشيطان أبدًا."),
        "dua_ibrahim_children_protection" to DuaText("حفظ البلد والذرية", "رب اجعل هذا البلد آمنًا واجنبني وبني أن نعبد الأصنام.", "دعاء إبراهيم عليه السلام لحفظ البلد والذرية.", "دعاء الثبات على التوحيد."),
        "dua_drinking_milk" to DuaText("عند شرب اللبن", "اللهم بارك لنا فيه وزدنا منه.", "عند شرب اللبن.", "اللبن يُجزئ عن الطعام والشراب معًا."),
        "dua_iftar_host" to DuaText("الإفطار عند شخص آخر", "أفطر عندكم الصائمون، وأكل طعامكم الأبرار، وصلت عليكم الملائكة.", "عند الإفطار عند شخص آخر.", "دعاء النبي ﷺ للمُضيف."),
        "dua_seeing_first_fruit" to DuaText("عند رؤية أول ثمرة", "اللهم بارك لنا في ثمارنا وبارك لنا في مدينتنا وبارك لنا في صاعنا وبارك لنا في مدّنا.", "عند رؤية أول ثمرة في الموسم.", "دعاء البركة في الرزق والبلد."),
        "dua_good_news" to DuaText("عند سماع خبر سار", "الحمد لله الذي بنعمته تتم الصالحات.", "عند سماع خبر سار (وسجود الشكر).", "كان النبي ﷺ يقولها عند رؤية ما يحب."),
        "dua_looking_mirror" to DuaText("عند النظر في المرآة", "اللهم كما حسّنت خَلقي فحسّن خُلقي.", "عند النظر في المرآة.", "كان النبي ﷺ يدعو بهذا الدعاء."),
        "dua_rabbana_taqabbal" to DuaText("قبول الأعمال", "ربنا تقبل منا إنك أنت السميع العليم. وتب علينا إنك أنت التواب الرحيم.", "دعاء إبراهيم وإسماعيل عليهما السلام عند بناء الكعبة.", "دعاء قبول العمل الصالح بعد إتمامه."),
    )
}
